import{f as o,o as a,c,a2 as d}from"./chunks/framework.BtbFyp-E.js";const g=JSON.parse('{"title":"13 — Pasarelas de pago e Interbanking","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/13-pasarelas-de-pago-e-interbanking.md","filePath":"relevamiento/reglas-negocio/13-pasarelas-de-pago-e-interbanking.md","lastUpdated":null}'),t={name:"relevamiento/reglas-negocio/13-pasarelas-de-pago-e-interbanking.md"};function r(n,e,s,i,l,p){return a(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="_13-—-pasarelas-de-pago-e-interbanking" tabindex="-1">13 — Pasarelas de pago e Interbanking <a class="header-anchor" href="#_13-—-pasarelas-de-pago-e-interbanking" aria-label="Permalink to &quot;13 — Pasarelas de pago e Interbanking&quot;">​</a></h1><p>Este documento describe, a partir del código descompilado, cómo Procoop se comunica con las <strong>pasarelas de pago online</strong> (links de pago, QR, botones, débito automático por API) y con <strong>Interbanking</strong> (saldos, extractos y conciliación bancaria, más los archivos de pago a proveedores y sueldos).</p><p>Complementa, sin repetir, a:</p><ul><li><a href="./05-cobranzas-cajas-y-entes-recaudadores">05 — Cobranzas, cajas y entes recaudadores</a>: modelo de tablas <code>PAGOS360*</code>, clase base <code>EntidadDigital</code>, importadores de rendición por archivo, registración de la cobranza (<code>clsRegistracionCobranza.RegistrarPago</code>), débito automático por archivo.</li><li><a href="./10-integraciones-externas">10 — Integraciones externas</a>: portal CoopOnline / Firebase, app, mail, SMS, WhatsApp, entes reguladores.</li><li><a href="./09-parametros-y-configuracion">09 — Parámetros y configuración</a>: los nombres de parámetros (<code>Busca_V2_*</code>) que se citan acá por número.</li></ul><p><strong>Convenciones de rutas.</strong> Todas las rutas son relativas a <code>procoop-relevamiento/binarios/decompilado/</code>. Abreviaturas: <code>PMW/</code> = <code>ProMod_WebService/WebService.</code>; <code>RN.Cob/</code> = <code>ReglasNegocio/ReglasNegocio.Cobranzas/</code>; <code>RN.Tes/</code> = <code>ReglasNegocio/ReglasNegocio.Tesoreria/</code>; <code>Agente/</code> = <code>ReglasNegocio/Agente.Clases/</code>. Ejemplo: <code>PMW/Pagos360/Service.cs:19</code> = <code>ProMod_WebService/WebService.Pagos360/Service.cs</code>, línea 19.</p><p><strong>Política de secretos.</strong> No se transcribe ningún valor de credencial. En <code>ProMod_WebService</code> <strong>no se encontraron credenciales hardcodeadas</strong>: todas salen de parámetros, de la tabla <code>INTERBANKING</code> o de tablas de configuración. Los hallazgos de seguridad (secretos que terminan en logs, en la base o en el portal) están en la <a href="#17-hallazgos-de-seguridad">sección 17</a>.</p><hr><h2 id="_1-panorama" tabindex="-1">1. Panorama <a class="header-anchor" href="#_1-panorama" aria-label="Permalink to &quot;1. Panorama&quot;">​</a></h2><p><code>ProMod_WebService.dll</code> (.NET Framework 4.6.1, referencia <code>Newtonsoft.Json</code>, <code>System.Net.Http</code> y el SDK oficial <code>MercadoPago.dll</code> 2.3.8; <code>ProMod_WebService/ProMod_WebService.csproj</code>) es <strong>solo la capa de transporte HTTP</strong>: un namespace por proveedor con una clase <code>Service</code> (arma y envía el request) y una clase estática <code>Functions</code> (un método por endpoint, con las credenciales en propiedades estáticas) más los DTO de request/response. <strong>Toda la lógica de negocio</strong> (qué se cobra, cómo se concilia, cuándo se marca pagado) está en <code>ReglasNegocio</code>, en subclases de <code>EntidadDigital</code> (ver doc 05 §7).</p><p>El código de API de cada solicitud se guarda en <code>PAGOS360.API</code> (enum <code>EntidadDigital.API</code>):</p><table tabindex="0"><thead><tr><th>API</th><th>Pasarela</th><th>Tipo de integración</th><th>Base URL (producción)</th><th>Autenticación</th><th>Clase de negocio</th></tr></thead><tbody><tr><td>0</td><td><strong>Pagos360</strong></td><td>Link de pago, QR dinámico y estático, débito tarjeta/CBU, reportes</td><td><code>api.pagos360.com</code>, <code>qr.pagos360.com</code></td><td>Bearer API key (param 901 / 2922)</td><td><code>RN.Cob/clsPagos360.cs</code></td></tr><tr><td>1</td><td><strong>SIRO</strong> (Banco Roela)</td><td>Botón de pago, base de deuda, listados, QR estático</td><td><code>siropagos.bancoroela.com.ar</code>, <code>apisiro.bancoroela.com.ar</code>, <code>apisesion.bancoroela.com.ar</code></td><td>Usuario/clave → token de sesión (2492/2493, 2804/2805)</td><td><code>RN.Cob/clsSIRO.cs</code></td></tr><tr><td>2</td><td><strong>MercadoPago</strong></td><td>Preferencia de Checkout Pro (link)</td><td><code>api.mercadopago.com</code> (SDK)</td><td>Access token (2553)</td><td><code>RN.Cob/clsMercadoPago.cs</code></td></tr><tr><td>3</td><td>OffLine</td><td>Sin API: cupón para pagar en ente presencial</td><td>—</td><td>—</td><td>ver doc 05</td></tr><tr><td>4</td><td><strong>NaranjaX</strong> (Ranty)</td><td>QR dinámico en caja</td><td><code>api.ranty.io</code> + <code>services.apinaranja.com</code></td><td>OAuth2 client_credentials (2756-2758)</td><td><code>RN.Cob/clsNaranjaX.cs</code></td></tr><tr><td>5</td><td><strong>Macro – Click de Pago</strong> (PlusPagos / ASJ Servicios)</td><td>Botón de pago (formulario en el portal)</td><td><code>botonpp.asjservicios.com.ar:8082/v1</code></td><td>GUID + frase → token (2765-2768)</td><td><code>RN.Cob/clsMacro.cs</code></td></tr><tr><td>6</td><td><strong>PayFun</strong></td><td>Checkout (tarjeta, DEBIN, Pago Fácil)</td><td><code>checkouts.payfun.com.ar/v2</code></td><td>Headers <code>x-api-key</code> + <code>x-access-token</code> (2793/2794)</td><td><code>RN.Cob/clsPayFun.cs</code></td></tr><tr><td>7</td><td><strong>Pagos TIC</strong> (PayPerTIC)</td><td>Checkout</td><td><code>api.paypertic.com</code> + <code>a.paypertic.com</code></td><td>OAuth2 password grant (2877-2883)</td><td><code>RN.Cob/clsPagostic.cs</code></td></tr><tr><td>8</td><td><strong>SiPago</strong> (Geopagos)</td><td>Checkout por órdenes</td><td><code>api.sipago.coop</code> + <code>auth.prd.geopagos.io</code></td><td>OAuth2 client_credentials (2956-2960)</td><td><code>RN.Cob/clsSiPago.cs</code></td></tr><tr><td>9</td><td><strong>ProntoPago</strong></td><td>QR impreso en factura (por lotes)</td><td><code>qrfacturas.prontopago.com.ar</code></td><td>Clave pública/privada → token (2969-2971)</td><td><code>RN.Cob/clsProntoPago.cs</code></td></tr><tr><td>10</td><td><strong>ProvinciaNet</strong> (Bapro)</td><td>QR en factura (por lotes)</td><td><code>netqr-bff-tenant.provincianet.com.ar</code></td><td>Header <code>x-api-key</code> (3046)</td><td><code>RN.Cob/clsProvinciaNet.cs</code></td></tr><tr><td>11</td><td><strong>Helipagos</strong></td><td>Checkout + código de barras + QR</td><td><code>api.helipagos.com</code></td><td>Bearer API key (3077)</td><td><code>RN.Cob/clsHelipagos.cs</code></td></tr><tr><td>—</td><td><strong>Interbanking</strong></td><td>Cuentas, saldos y movimientos (solo lectura)</td><td><code>api-gw.interbanking.com.ar</code>, <code>auth.interbanking.com.ar</code></td><td>OAuth2 client_credentials (tabla <code>INTERBANKING</code>)</td><td><code>RN.Tes/clsInterbanking.cs</code></td></tr><tr><td>—</td><td>BancoSangre (CoopOnline)</td><td>Consulta de resumen de tarjeta de terceros</td><td><code>www.bancodesangre.cooponlineweb.com.ar</code></td><td>Ninguna</td><td><code>RN.Cob/clsTerceros.cs</code></td></tr></tbody></table><p><strong>No existen en el código</strong> integraciones por API con: Red Link (solo archivos, doc 05), Pago Fácil / Rapipago online como tales (solo se llega a ellos a través de los códigos de barras que devuelven Pagos360, Helipagos o PayFun), MODO u otras billeteras como API propia (los QR son interoperables y los emite la pasarela), Prisma/Decidir/Payway, ni transferencias o pagos por API de Interbanking. Se buscaron URLs y nombres de estos proveedores en todo el descompilado sin resultados.</p><hr><h2 id="_2-arquitectura-comun-de-promod-webservice" tabindex="-1">2. Arquitectura común de <code>ProMod_WebService</code> <a class="header-anchor" href="#_2-arquitectura-comun-de-promod-webservice" aria-label="Permalink to &quot;2. Arquitectura común de \`ProMod_WebService\`&quot;">​</a></h2><h3 id="_2-1-patron-de-transporte" tabindex="-1">2.1 Patrón de transporte <a class="header-anchor" href="#_2-1-patron-de-transporte" aria-label="Permalink to &quot;2.1 Patrón de transporte&quot;">​</a></h3><p>Cada <code>Service.Invoke&amp;lt;TRequest,TResponse&gt;(método, funcion, request)</code>:</p><ol><li>Arma la URL <code>base + funcion</code> (algunos servicios eligen entre dos o tres bases según el nombre de la función, p. ej. SIRO <code>PMW/SIRO/Service.cs:29</code>, SiPago <code>PMW/SiPago/Service.cs:27</code>, Pagos360 <code>Get_Url</code> <code>PMW/Pagos360/Service.cs:147-163</code>).</li><li>Crea un <code>HttpWebRequest</code>, setea <code>Content-Type: application/json</code>, el header de autenticación y, en Pagos360/Interbanking, fuerza TLS 1.2.</li><li>Serializa el request con Newtonsoft (<code>NullValueHandling.Ignore</code> en general) y lo escribe en el cuerpo.</li><li>Lee la respuesta; si es <code>&quot;[]&quot;</code> devuelve el error &quot;No se encontraron resultados&quot;; si no, deserializa con <code>CoreUtils.Deserializar&amp;lt;T&gt;</code> (<code>ProMod_WebService/WebService.Util/CoreUtils.cs:45-59</code>).</li><li>Ante <code>WebException</code> traduce el código HTTP a un <strong>string de error</strong> (p. ej. 400/409 → objeto <code>BadRequest</code> del proveedor; 401 → <code>error_description</code>; 500 → &quot;No fue posible establecer comunicación… reintente&quot;), que vuelve por parámetro <code>out</code>.</li></ol><p>Consecuencias del patrón:</p><ul><li><strong>No hay reintentos automáticos</strong> en ningún servicio propio, ni timeouts configurados (se usan los defaults de <code>HttpWebRequest</code>). El único con reintentos es MercadoPago, porque el SDK oficial trae <code>DefaultRetryStrategy</code> (2 reintentos, backoff exponencial 0,5–5 s, solo para métodos idempotentes o POST con <code>X-Idempotency-Key</code>, en 409 y 5xx; <code>MercadoPago/MercadoPago.Config/MercadoPagoConfig.cs:141</code>, <code>MercadoPago/MercadoPago.Http/DefaultRetryStrategy.cs:20-69</code>).</li><li>El &quot;reintento&quot; real es de negocio: el Agente vuelve a consultar en cada ciclo, y la caja reconsulta con un timer (§2.4).</li><li><strong>Credenciales en propiedades estáticas</strong> de <code>Functions</code>: un proceso = una cooperativa. En MercadoPago el setter solo asigna el token si todavía no había uno (<code>PMW/MercadoPagos/Functions.cs:21-35</code>), así que cambiar el token exige reiniciar el proceso.</li><li><strong>No hay ambiente de homologación</strong>: todas las URLs son de producción y están hardcodeadas (Interbanking incluso lleva <code>/api/prod/</code> en la ruta). En Pagos360 la clave se usa como <code>key.Replace(&quot;TEST&quot;, &quot;&quot;)</code> (<code>PMW/Pagos360/Service.cs:35</code>), lo que sugiere que las claves de prueba se distinguían por prefijo; en base DEMO la clave se deja vacía (<code>RN.Cob/clsPagos360.cs:354-365</code>).</li><li><code>CoreUtils.Deserializar</code> escribe la excepción en <code>LogProcoop.txt</code>; además <code>CoreUtils.cs:65</code> tiene hardcodeados dos nombres de equipo de desarrollo (no son secretos).</li></ul><h3 id="_2-2-ciclo-de-vida-comun-de-una-solicitud" tabindex="-1">2.2 Ciclo de vida común de una solicitud <a class="header-anchor" href="#_2-2-ciclo-de-vida-comun-de-una-solicitud" aria-label="Permalink to &quot;2.2 Ciclo de vida común de una solicitud&quot;">​</a></h3><p>El ciclo es el mismo para todas las pasarelas; cambia el &quot;conector&quot;. Estados de <code>PAGOS360.ESTADO</code>: 0 Pendiente, 1 Registrado, 2 Pagado, 3 Imputado, 4 Anulado, 5 Revertido, 6 Rechazado.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Crear solicitud (EntidadDigital.Generar_Solicitud / Crear_PAGOS360)</span></span>
<span class="line"><span>   → fila PAGOS360 (ESTADO 0) + PAGOS360_ITEMS (facturas)        [doc 05 §7]</span></span>
<span class="line"><span>   → si hay un link idéntico de los últimos 10 min, se reutiliza  [doc 05 §7]</span></span>
<span class="line"><span>2. Registrar_Solicitudes: llamar a la pasarela, guardar ID externo,</span></span>
<span class="line"><span>   link/QR/código de barras → ESTADO 1</span></span>
<span class="line"><span>3. El socio paga (portal, app, caja con QR, cupón con barras)</span></span>
<span class="line"><span>4. Confirmación (tres caminos, ver 2.3)</span></span>
<span class="line"><span>   → Obtener_Pago: re-consulta la pasarela, inserta PAGOS360_PAGOS</span></span>
<span class="line"><span>     (deduplicando por id de pago externo) → ESTADO 2</span></span>
<span class="line"><span>5. Registración: clsRegistracionCobranza.RegistrarPago (planilla de</span></span>
<span class="line"><span>   caja, recibo; prefijos 41/42/43) → ESTADO 3 (Imputado)       [doc 05]</span></span>
<span class="line"><span>6. Excepciones: anulación (ESTADO 4), contracargo/reversión (5),</span></span>
<span class="line"><span>   rechazo (6)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>Los métodos abstractos que cada conector implementa están en <code>RN.Cob/EntidadDigital.cs:240-299</code> (<code>Registrar_Solicitudes</code>, <code>Obtener_Pago</code>, <code>Importar_Pagos</code>, <code>Importar_PagosAPI</code>, <code>InicializarTimer</code>, <code>GenerarQrCaja</code>, etc.). Varios conectores dejan alguno en <code>NotImplementedException</code> (se indica en cada sección).</p><h3 id="_2-3-como-se-entera-procoop-de-un-pago-webhook-polling-o-archivo" tabindex="-1">2.3 Cómo se entera Procoop de un pago: webhook, polling o archivo <a class="header-anchor" href="#_2-3-como-se-entera-procoop-de-un-pago-webhook-polling-o-archivo" aria-label="Permalink to &quot;2.3 Cómo se entera Procoop de un pago: webhook, polling o archivo&quot;">​</a></h3><ol><li><strong>Webhook vía CoopOnline (no vía Procoop).</strong> Las URLs de notificación que se le pasan a la pasarela tienen la forma <code>{url}?TipCobrador={pasarela}&amp;CodPag={COD_PAG}</code> y apuntan al backend de CoopOnline del proveedor (parámetros 3139 MP, 2796 PayFun, 2959 SiPago, 3079 Helipagos; NaranjaX está hardcodeado). Procoop <strong>no expone endpoints HTTP</strong>. CoopOnline escribe el evento en Firebase y el Agente lo escucha (<code>OnAsync(&quot;Cobranza_&quot;+cliente)</code>, <code>Agente/clsWeb_CoopOnline.cs:947</code> y <code>:974</code>). Luego <code>clsWeb_CoopOnline.ConsultarPago&amp;lt;T&gt;</code> (<code>:2032-2113</code>) despacha a <code>Obtener_Pago</code> de la pasarela correspondiente, que <strong>vuelve a consultar la API</strong>: el webhook es solo un disparador y la verdad se obtiene consultando. No hay validación de firma de webhooks en ningún lado (tampoco haría falta en Procoop, porque la consulta posterior es autenticada). Excepciones: ProvinciaNet confía en el importe que llega desde el portal (§12) y SIRO, para pagos sin solicitud previa, crea la fila <code>PAGOS360</code> a partir de la consulta (§4).</li><li><strong>Polling por lote en el Agente.</strong> <code>clsServicio_Procoop.Procesar_Archivo_Rendicion</code> (<code>ReglasNegocio/RN.Varios.Generales/clsServicio_Procoop.cs:753-860</code>) toma la entidad por defecto (param 2996, exige mail de errores 3025), consulta <strong>los últimos 4 días</strong> vía <code>Importar_PagosAPI</code> (Pagos360 día por día; SIRO por rango), marca los pagos encontrados como <code>ESTADO = 2</code> / procesados y después corre el importador de rendición PR estándar (<code>Importador_Base.Get_Importador(...).Importar(&quot;&quot;)</code>), que registra la cobranza igual que una rendición por archivo (doc 05). Los procesos 9 y 10 de línea de comandos de Procoop también disparan procesos de Pagos360 (<a href="./09-parametros-y-configuracion">doc 09</a>, modos de línea de comandos).</li><li><strong>Polling en la caja (QR).</strong> Al mostrar un QR en caja, <code>InicializarTimer</code> consulta el estado cada pocos segundos durante <strong>hasta 10 minutos</strong> (Pagos360 <code>RN.Cob/clsPagos360.cs:893-908</code>; SIRO <code>RN.Cob/clsSIRO.cs:1009-1024</code>; NaranjaX <code>RN.Cob/clsNaranjaX.cs:304-325</code>).</li></ol><p>En el camino por webhook la registración la hace <code>clsWeb_CoopOnline.AutorizarCobranza</code> (<code>Agente/clsWeb_CoopOnline.cs:1679-1760</code>): valida que la suma de <code>PAGOS360_PAGOS</code> coincida con lo que se calcula <strong>hoy</strong> para las facturas (si no, registra &quot;Los importes de la cobranza no coinciden&quot; y no imputa) y llama a <code>RegistrarCobranza</code> (<code>:2170-2187</code>) → <code>clsRegistracionCobranza.RegistrarPago</code> con el medio de pago que corresponde a la entidad (<code>GetMedioPago</code>) y el parámetro 2452 (generar siempre recibo oficial).</p><h3 id="_2-4-eleccion-de-la-pasarela" tabindex="-1">2.4 Elección de la pasarela <a class="header-anchor" href="#_2-4-eleccion-de-la-pasarela" aria-label="Permalink to &quot;2.4 Elección de la pasarela&quot;">​</a></h3><p><code>clsWeb_CoopOnline.GenerarSolicitud</code> (<code>Agente/clsWeb_CoopOnline.cs:1971-2030</code>) elige la entidad según el canal de pago del portal (<code>CANALES_PAGOS.API</code>) o, en su defecto, el parámetro 2774 (entidad por defecto en cobranza web). Si no hay, cae en SIRO (si 2500 &quot;acepta SIRO&quot; y hay usuario 2492), luego Pagos360 (si hay clave 901 y 904) y, si 2645 = &quot;solo pago offline&quot;, en OffLine.</p><hr><h2 id="_3-pagos360" tabindex="-1">3. Pagos360 <a class="header-anchor" href="#_3-pagos360" aria-label="Permalink to &quot;3. Pagos360&quot;">​</a></h2><p>La integración más completa: links de pago con dos vencimientos, QR dinámico y estático, débito automático con tarjeta y CBU, reportes de cobranza y de contracargos.</p><h3 id="_3-1-ambiente-autenticacion-y-transporte" tabindex="-1">3.1 Ambiente, autenticación y transporte <a class="header-anchor" href="#_3-1-ambiente-autenticacion-y-transporte" aria-label="Permalink to &quot;3.1 Ambiente, autenticación y transporte&quot;">​</a></h3><ul><li>Bases (<code>PMW/Pagos360/Service.cs:19</code>, <code>Get_Url</code> <code>:147-163</code>): <code>https://api.pagos360.com/</code> para todo; <code>https://qr.pagos360.com/</code> para <code>save-qr-data</code>; QR estático en la URL del parámetro 2921 o, si está vacío, en el host de QR.</li><li>Header <code>authorization: Bearer {key}</code>; TLS 1.2 forzado.</li><li>Clave: parámetro 901 (vacía en base DEMO); para el QR estático por caja, clave 2922 (<code>RN.Cob/clsPagos360.cs:354-365</code>, <code>Get_Config</code> <code>:384-417</code>). Los endpoints de checkout QR de caja se invocan <strong>sin</strong> clave.</li><li>Log de depuración: si existe el archivo <code>c:\\procoop\\Log360.txt</code>, se le agrega la URL, el header de autorización completo y el cuerpo de cada request (<code>PMW/Pagos360/Service.cs:39-76</code>). Ver §17.</li><li>Errores: 400/409 → <code>BadRequest.Get_Error</code> (lista de errores de validación); 401 → <code>error_description</code>; 403/404 → <code>message</code>; 405 → texto crudo; otros → <code>GeneralError</code>.</li></ul><h3 id="_3-2-endpoints-pmw-pagos360-functions-cs" tabindex="-1">3.2 Endpoints (<code>PMW/Pagos360/Functions.cs</code>) <a class="header-anchor" href="#_3-2-endpoints-pmw-pagos360-functions-cs" aria-label="Permalink to &quot;3.2 Endpoints (\`PMW/Pagos360/Functions.cs\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Uso</th><th>Método y ruta</th><th>Línea</th></tr></thead><tbody><tr><td>Crear solicitud de pago</td><td><code>POST payment-request</code></td><td>:44</td></tr><tr><td>Consultar solicitud</td><td><code>GET payment-request/{id}</code></td><td>:49</td></tr><tr><td>Reporte de cobranza del día</td><td><code>GET report/collection/{dd-MM-yyyy}</code></td><td>:54</td></tr><tr><td>Datos de QR dinámico</td><td><code>POST save-qr-data</code> (host QR)</td><td>:59</td></tr><tr><td>Crear QR estático (devuelve imagen base64)</td><td><code>POST create-qr</code></td><td>:64</td></tr><tr><td>Estado de QR</td><td><code>GET status/{id}</code></td><td>:69</td></tr><tr><td>Nueva transacción en QR estático</td><td><code>PUT new-transaction?data=</code></td><td>:74</td></tr><tr><td>Pagos por referencia/fechas (QR estático)</td><td><code>GET payments?external_reference&amp;paid_at_gte&amp;paid_at_lte</code></td><td>:79</td></tr><tr><td>Checkout QR (caja)</td><td><code>POST checkout/qr/pay</code>; <code>GET payment-request/qr/{uuid}</code></td><td>:84, :89</td></tr><tr><td>Saldos de la cuenta</td><td><code>GET account/balances</code></td><td>:94</td></tr><tr><td>Adhesión tarjeta</td><td><code>POST/GET card-adhesion</code>, <code>PUT card-adhesion/{id}/cancel</code></td><td>:99-110</td></tr><tr><td>Débito con tarjeta</td><td><code>POST/GET card-debit-request</code>, <code>PUT …/cancel</code></td><td>:114-125</td></tr><tr><td>Adhesión CBU</td><td><code>POST/GET adhesion</code>, <code>PUT adhesion/{id}/cancel</code></td><td>:129-140</td></tr><tr><td>Débito por CBU</td><td><code>POST/GET debit-request</code>; cancelar con <strong><code>GET</code></strong> <code>debit-request/{id}/cancel</code></td><td>:144-155</td></tr><tr><td>Reporte de contracargos</td><td><code>GET report/chargeback/{fecha}</code></td><td>:159</td></tr></tbody></table><p>La cancelación de débito CBU usa <code>GET</code> mientras el resto de las cancelaciones usa <code>PUT</code>: probable error (duda abierta).</p><p><strong>Request de solicitud</strong> (<code>PaymentRequest</code>): <code>description</code>, <code>external_reference</code> (= <code>COD_PAG</code>), <code>first_due_date</code> / <code>first_total</code>, <code>second_due_date</code> / <code>second_total</code>, <code>payer_name</code>, <code>payer_email</code>, <code>back_url_success/pending/rejected</code>, <code>metadata</code>, <code>excluded_channels</code>, <code>excluded_card_brands</code>, <code>excluded_installments</code>.</p><p><strong>Respuesta</strong>: <code>id</code>, <code>state</code>, <code>checkout_url</code>, <code>barcode</code>, <code>barcode_url</code>, <code>pdf_url</code>, <code>rapipago_barcode</code>, <code>pago_facil_first_due_date_barcode</code> / <code>…second…</code>, y <code>request_result[]</code> con <code>id</code>, <code>type</code>, <code>channel</code>, <code>paid_at</code>, <code>available_at</code>, <code>amount</code>, <code>gross_fee</code>, <code>net_fee</code>, <code>fee_iva</code>, <code>net_amount</code>. El reporte de cobranza devuelve <code>total_collected</code> y <code>data[]</code> (<code>request_id</code>, <code>external_reference</code>, <code>payment_date</code>, <code>channel</code>, <code>amount_paid</code>, <code>net_fee</code>, <code>iva_fee</code>, <code>net_amount</code>).</p><p>Así, Pagos360 es también la vía por la que una factura queda <strong>pagable en Rapipago y Pago Fácil online</strong> (códigos de barras devueltos por la API) sin un convenio directo con esos entes.</p><h3 id="_3-3-flujo-de-link-de-pago" tabindex="-1">3.3 Flujo de link de pago <a class="header-anchor" href="#_3-3-flujo-de-link-de-pago" aria-label="Permalink to &quot;3.3 Flujo de link de pago&quot;">​</a></h3><p><code>clsPagos360.Registrar_Solicitudes</code> (<code>RN.Cob/clsPagos360.cs:2287-2428</code>):</p><ul><li>Medios habilitados por las banderas de <code>MEDIOS</code>; los no habilitados se mandan en <code>excluded_channels</code> (<code>Get_MedioPago</code> <code>:3036-3050</code>: <code>QR</code>, <code>wire_transfer</code>, <code>DEBIN</code>, <code>banelco_pmc</code>, <code>link_pagos</code>, <code>non_banking</code>, <code>debit_card</code>, <code>credit_card</code>). Marcas de tarjeta excluidas según parámetro 2743 (códigos en <code>:3068</code>); cuotas excluidas según 2720.</li><li>Vencimientos e importes: primer y segundo vencimiento de la factura (con recargo calculado por las reglas de doc 05).</li><li>URLs de retorno: parámetros 902 / 903 / 907 o, si no, <code>URL_PWEB</code> + &quot;1/2/3&quot;.</li><li>QR unitario si el parámetro 2726 lo indica y el código postal (2760) tiene 8 caracteres.</li><li>Guarda <code>ID_ENTIDAD</code>, URLs y códigos de barra actualizando <code>PAGOS360</code> con <strong>SQL armado por concatenación</strong> (<code>:2417</code>).</li><li>QR masivos para imprimir en facturas: <code>GenerarQr360</code> en lotes de hasta 10.000 (<code>:2430-2497</code>).</li></ul><p><strong>Confirmación</strong> — <code>Obtener_Pago</code> (<code>:742-866</code>):</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si es débito → Get_CardDebitRequest / Get_DebitRequest</span></span>
<span class="line"><span>si no       → Get_PaymentRequest(id); exige state == &quot;paid&quot;</span></span>
<span class="line"><span>para cada request_result que no sea rejected_*:</span></span>
<span class="line"><span>    si ya existe PAGOS360_PAGOS con ese ID_360 → saltear</span></span>
<span class="line"><span>    importe negativo si type == chargeback_payment_request_result</span></span>
<span class="line"><span>    FECHA_REN = available_at; CHANNEL = channel; comisiones e IVA de comisión</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>Conciliación por reporte</strong> — <code>Importar_PagosAPI</code> (<code>:2819-2895</code>): por cada día pide <code>report/collection</code>, descarta las filas &quot;REVERSIÓN&quot;/&quot;REINTEGRO&quot; y las del QR estático de caja, mapea el ID en pagos por QR y llama a <code>Obtener_Pago</code>. Si llega un <code>request_id</code> que no existe en <code>PAGOS360</code> (pago generado desde la app de Pagos360 u otro origen), <code>Importar_Pagos_Inexistentes</code> (<code>:2985-3034</code>) crea la fila (&quot;Pago App&quot;). El parámetro 2981 habilita obtener las cobranzas vía API en lugar de archivo.</p><h3 id="_3-4-qr-en-caja" tabindex="-1">3.4 QR en caja <a class="header-anchor" href="#_3-4-qr-en-caja" aria-label="Permalink to &quot;3.4 QR en caja&quot;">​</a></h3><ul><li><strong>Dinámico</strong> (<code>GenerarQrCaja</code> <code>:2499-2527</code>): checkout QR de un uso + polling de 10 min (§2.3).</li><li><strong>Estático por caja</strong> (tabla <code>CAJAS_QR</code>, parámetros 2920-2922): un QR fijo por puesto; al cobrar se hace <code>PUT new-transaction</code> con el importe y luego se busca el pago con <code>GET payments</code>, emparejando <strong>por fecha e importe</strong> (<code>Get_Pago_QrEstatico</code> <code>:910-939</code>). Si dos socios pagan el mismo importe el mismo día en la misma caja, la asignación es ambigua.</li></ul><h3 id="_3-5-debito-automatico-tarjeta-y-cbu" tabindex="-1">3.5 Débito automático (tarjeta y CBU) <a class="header-anchor" href="#_3-5-debito-automatico-tarjeta-y-cbu" aria-label="Permalink to &quot;3.5 Débito automático (tarjeta y CBU)&quot;">​</a></h3><ul><li>Adhesión: <code>card-adhesion</code> (tarjeta) o <code>adhesion</code> (CBU). Estados que devuelve: <code>pending_to_sign</code>, <code>signed</code>, <code>canceled</code>; <code>Actualizar_EstadosDebitos</code> los sincroniza (<code>:1369-1450</code>).</li><li>Débitos: <code>Registrar_Solicitudes_Debito</code> (<code>:2559-2635</code>). Tarjeta: se informa mes/año; <strong>si el día del primer vencimiento es mayor o igual al parámetro 2779 (por defecto 19), el débito pasa al mes siguiente</strong>. CBU: <code>debit-request</code> con primer y segundo vencimiento.</li><li>Baja: <code>Cancelar_Debito</code> (<code>:1261-1329</code>) cancela en Pagos360 y deja <code>SUMSOC.DEB_TARJ = false</code> y la fecha de baja.</li><li>El débito por archivo con bancos y tarjetas (no por API) está en doc 05 §6.</li></ul><h3 id="_3-6-contracargos-reversiones-y-anulaciones" tabindex="-1">3.6 Contracargos, reversiones y anulaciones <a class="header-anchor" href="#_3-6-contracargos-reversiones-y-anulaciones" aria-label="Permalink to &quot;3.6 Contracargos, reversiones y anulaciones&quot;">​</a></h3><ul><li><code>Get_PagosRechazados</code> (<code>:1452-1506</code>) usa <code>report/chargeback/{fecha}</code>. Una reversión pasa la solicitud a <code>ESTADO = 5</code> (<code>CambiarEstadoReversion</code> <code>:3152</code>) y genera un anticipo/nota que vuelve a dejar la deuda (<code>EntidadDigital.Crear_Anticipo_Rever</code>, <code>RN.Cob/EntidadDigital.cs:301-444</code>, parámetros 2999-3002, 3059, 3073, 1008 vendedor, 2409 tipo de cuota). También se pueden levantar reversiones desde archivo (<code>Buscar_SolicitudesRevertidas</code> <code>:3163</code>).</li><li><code>AnularCobranza</code> (<code>:3118-3135</code>) desvincula la planilla (<code>ID_PLA</code>) y devuelve la solicitud a <code>ESTADO = 2</code> para reimputarla.</li><li><strong>No hay devoluciones (refunds) por API</strong> en Pagos360 ni en ninguna otra pasarela.</li></ul><h3 id="_3-7-totem-de-autogestion" tabindex="-1">3.7 Tótem de autogestión <a class="header-anchor" href="#_3-7-totem-de-autogestion" aria-label="Permalink to &quot;3.7 Tótem de autogestión&quot;">​</a></h3><p><code>GetHTMLRequest</code> (<code>:367-382</code>) carga un HTML embebido (<code>Pagos360.html</code> del ensamblado de AutoGestión) e inyecta <strong>número de tarjeta, vencimiento y código de seguridad</strong> para enviarlos al formulario de Pagos360. Los datos de tarjeta pasan por memoria de Procoop (ver §17).</p><hr><h2 id="_4-siro-banco-roela" tabindex="-1">4. SIRO (Banco Roela) <a class="header-anchor" href="#_4-siro-banco-roela" aria-label="Permalink to &quot;4. SIRO (Banco Roela)&quot;">​</a></h2><p>SIRO es a la vez ente recaudador por archivo (doc 05 §5.2, incluida la rama propia de LAG) y API. Acá solo la parte API.</p><h3 id="_4-1-ambiente-y-autenticacion" tabindex="-1">4.1 Ambiente y autenticación <a class="header-anchor" href="#_4-1-ambiente-y-autenticacion" aria-label="Permalink to &quot;4.1 Ambiente y autenticación&quot;">​</a></h3><ul><li>Bases (<code>PMW/SIRO/Service.cs:19-29</code>): <code>https://siropagos.bancoroela.com.ar/</code> para las funciones que empiezan con <code>Api/</code> (botón de pago); <code>https://apisiro.bancoroela.com.ar/</code> para la API de gestión (<code>siro/…</code>); sesión en <code>https://apisesion.bancoroela.com.ar/</code>.</li><li><code>Login</code> (<code>PMW/SIRO/Functions.cs:62-119</code>): con usuario/clave → <code>POST Api/Sesion</code> (botón); con CUIT + clave de gestión → <code>POST Auth/Sesion</code> en el host de sesión. El token se <strong>reutiliza durante 10 minutos</strong>.</li><li>Credenciales: 2492 usuario, 2493 clave (botón); 2804 CUIT y 2805 clave (API de gestión), 2807 activa la API de gestión. Otros: 2494/2495 URLs OK/ERROR, 2500 acepta SIRO, 2775 verificar primer dígito 7, 2776 retardo entre consultas, 2939 QR estático, 2798-2802 datos del QR de caja, 3179 log de consultas; del módulo móvil, 43 convenio y 42 concepto.</li></ul><h3 id="_4-2-endpoints-pmw-siro-functions-cs-22-60" tabindex="-1">4.2 Endpoints (<code>PMW/SIRO/Functions.cs:22-60</code>) <a class="header-anchor" href="#_4-2-endpoints-pmw-siro-functions-cs-22-60" aria-label="Permalink to &quot;4.2 Endpoints (\`PMW/SIRO/Functions.cs:22-60\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Uso</th><th>Método y ruta</th></tr></thead><tbody><tr><td>Crear pago (botón)</td><td><code>POST Api/Pago</code> → <code>Url</code>, <code>Hash</code></td></tr><tr><td>Consultar pagos</td><td><code>POST Api/Pago/Consulta</code> (<code>FechaDesde/Hasta</code>, <code>idReferenciaOperacion</code>, <code>estado</code>, <code>nro_terminal</code>)</td></tr><tr><td>Resultado de un pago</td><td><code>GET Api/Pago/{hash}/{id_resultado}</code> → <code>PagoExitoso</code>, <code>Estado</code>, <code>IdOperacion</code>, <code>FechaOperacion</code>, <code>MensajeResultado</code></td></tr><tr><td>Informar base de deuda</td><td><code>POST siro/Pagos</code> (<code>base_pagos</code>, <code>confirmar_automaticamente</code>) → <code>nro_transaccion</code></td></tr><tr><td>Estado de la base</td><td><code>GET siro/Pagos/{nro}?obtener_informacion_base=true</code> (registros correctos/erróneos, totales)</td></tr><tr><td>Listado de rendición</td><td><code>POST siro/Listados/Proceso</code> (<code>fecha_desde/hasta</code>, <code>cuit_administrador</code>, <code>nro_empresa</code>)</td></tr><tr><td>QR estático</td><td><code>POST Api/Pago/StringQREstatico</code>, <code>POST Api/Pago/QREstatico</code></td></tr></tbody></table><p>Request del botón: <code>nro_cliente_empresa</code>, <code>nro_comprobante</code>, <code>Concepto</code>, <code>Importe</code>, <code>URL_OK</code>, <code>URL_ERROR</code>, <code>IdReferenciaOperacion</code>, <code>Detalle[]</code> (<code>descripcion</code>, <code>importe</code>).</p><h3 id="_4-3-flujo" tabindex="-1">4.3 Flujo <a class="header-anchor" href="#_4-3-flujo" aria-label="Permalink to &quot;4.3 Flujo&quot;">​</a></h3><ul><li><code>Registrar_Solicitudes</code> (<code>RN.Cob/clsSIRO.cs:1459-1534</code>): <code>nro_comprobante</code> = <code>COD_PAG</code> con ceros a 20; <code>nro_cliente_empresa</code> = <code>COD_PAG</code> a 9 dígitos + convenio; el detalle se ajusta para que sume exacto el total. Los errores se escriben en un archivo <code>errorSiro</code>.</li><li><code>Obtener_Pago</code> (<code>:1201-1403</code>): <strong>espera con <code>Thread.Sleep</code> el retardo del parámetro 2776 (por defecto 25 s) antes de cada consulta</strong> (<code>:1224</code>, también <code>:765</code>), consulta en una ventana de ±30 días alrededor de <code>FEC_REG</code>; si el resultado es <code>RECHAZADA</code> o <code>ERROR</code>, pasa a <code>ESTADO = 6</code> y llama a <code>clsWEB.MarcarPagoPendiente</code> para que el portal vuelva a mostrar la deuda. Si llega un pago sin solicitud (<code>COD_PAG = 0</code>) crea la fila <code>PAGOS360</code> (tipo 6) interpretando el detalle &quot;cod-suc-num&quot; y bloqueando el contador con <code>GetMaxValue_Boqueo</code>.</li><li>Conciliación: <code>Importar_PagosAPI</code> (<code>:420-480</code>) vía <code>Listados/Proceso</code>; publicación de deuda: <code>InformarBase</code> (<code>:482</code>) y <code>Consultar_Base</code> (<code>:512</code>).</li><li>QR de caja: <code>GenerarQRCaja</code> (<code>:342-361</code>) <strong>arma localmente</strong> un string EMVCo interoperable (identificador de Banco Roela, CUIT, CBU, MCC 8699, CRC); QR estático por terminal &quot;QrCaja{n}&quot; (<code>:958-1080</code>).</li></ul><hr><h2 id="_5-mercadopago" tabindex="-1">5. MercadoPago <a class="header-anchor" href="#_5-mercadopago" aria-label="Permalink to &quot;5. MercadoPago&quot;">​</a></h2><ul><li>Transporte: SDK oficial <code>MercadoPago.dll</code> 2.3.8 (<code>api.mercadopago.com</code>, <code>MercadoPagoConfig.cs:15</code>), envuelto en <code>PMW/MercadoPagos/Functions.cs</code>.</li><li>Credencial: access token en parámetro 2553 (<code>RN.Cob/clsMercadoPago.cs:46-62</code>); 2554 URL de éxito, 2555 de rechazo, 3139 URL de notificación, 2579 fecha desde la que se consultan pagos.</li><li><strong>Crear</strong>: <code>Send_PaymentRequest</code> crea una <strong>preferencia</strong> de Checkout Pro (<code>PMW/MercadoPagos/Functions.cs:37-80</code>): pagador, <code>back_urls</code>, <code>Expires = true</code>, <code>ExpirationDateTo</code>, <code>ExternalReference = COD_PAG</code>, <code>NotificationUrl</code>, ítems en ARS; exige HTTP 201 y devuelve el <code>InitPoint</code> (link). <code>Registrar_Solicitudes</code> (<code>RN.Cob/clsMercadoPago.cs:237-306</code>) manda un ítem por factura más un ítem &quot;Recargo&quot;; vence al final del día del primer vencimiento; la notificación es <code>{3139}?TipCobrador=MercadoPago&amp;CodPag=…</code> (<code>:274</code>); <code>ID_ENTIDAD</code> = id de preferencia.</li><li><strong>Consultar</strong>: búsqueda de pagos <code>approved</code> por rango de <code>date_approved</code> paginando de a 500 (<code>Functions.cs:82-124</code>) o por <code>external_reference</code> (<code>:126-156</code>).</li><li><strong>Registrar</strong>: <code>Registrar_Pago</code> (<code>RN.Cob/clsMercadoPago.cs:349-407</code>) deduplica por <code>ID_MERCADO_PAGO</code>, <code>FECHA_REN = MoneyReleaseDate</code>, <code>CHANNEL = PaymentMethodId</code>, <strong>comisiones en 0</strong> (no se toman de la API).</li><li>No implementa devoluciones, contracargos ni QR.</li></ul><hr><h2 id="_6-macro-–-click-de-pago-pluspagos" tabindex="-1">6. Macro – Click de Pago (PlusPagos) <a class="header-anchor" href="#_6-macro-–-click-de-pago-pluspagos" aria-label="Permalink to &quot;6. Macro – Click de Pago (PlusPagos)&quot;">​</a></h2><p>Botón de pago de Banco Macro operado por Soluciones Andinas / ASJ Servicios (&quot;PlusPagos&quot;).</p><ul><li>Base: <code>https://botonpp.asjservicios.com.ar:8082/v1</code> (<code>PMW/Macro/Service.cs:37</code>). Endpoints (<code>PMW/Macro/Functions.cs:16-24</code>): <code>POST sesion</code> (GUID de comercio + frase → <code>data</code> = token y <code>secretKey</code>), <code>GET transaction/{cod_pag}</code> con Bearer.</li><li>Parámetros (<code>RN.Cob/clsMacro.cs:278-292</code>): 2765 GUID, 2766 frase, 2767 clave secreta, 2768 token.</li><li><strong>Crear</strong>: no hay endpoint de creación. <code>Create_Request</code> (<code>:209-236</code>) arma un string separado por <code>;</code> con importe y cuenta cifrados con <code>AESEncrypter</code> del kit PlusPagos y lo guarda en <code>PAGOS360.URL_SUCCESS</code> (<code>Guardar_Request</code> <code>:238-258</code>, SQL concatenado); el portal CoopOnline lo recibe como <code>DatosMacro</code> (<code>Agente/clsWeb_CoopOnline.cs:1365-1368</code>) y arma el formulario <code>POST</code> al botón. El string <strong>incluye la clave secreta en claro</strong> (§17). Vencimiento: mañana.</li><li><strong>Confirmar</strong>: <code>Obtener_Pago</code> (<code>:138-192</code>) consulta <code>transaction/{cod_pag}</code>; exige estado <code>REALIZADA</code>, <code>montoBruto / 100</code> igual a <code>IMPORTE1</code> o <code>IMPORTE2</code> y fecha de pago posterior al registro.</li><li>Archivo de rendición (<code>Importar_Pagos</code> <code>:318-361</code>): posiciones fijas (<code>COD_PAG</code> en 279 largo 21, fecha en 224, importe en 77 largo 11).</li></ul><p><strong><code>PlusPagosSecurityKitNetFramework</code></strong> (v2.3.1, Soluciones Andinas 2018, &quot;Generador de hash… AES-256-CBC&quot;): <code>AESEncrypter.EncryptString</code> (clave = frase rellenada/cortada a 32 bytes, IV aleatorio antepuesto, Base64) y <code>SHA256Hash.Generate(ip, secretKey, comercio, sucursal, monto)</code> = SHA-256 de los campos unidos por <code>*</code>. <strong>Sí se usa</strong> (el AES, desde <code>clsMacro</code>), lo que corrige lo dicho en doc 10; el <code>SHA256Hash</code> no tiene usos en <code>ReglasNegocio</code> (el hash del formulario lo calcularía el portal; ver dudas).</p><hr><h2 id="_7-naranjax-ranty" tabindex="-1">7. NaranjaX (Ranty) <a class="header-anchor" href="#_7-naranjax-ranty" aria-label="Permalink to &quot;7. NaranjaX (Ranty)&quot;">​</a></h2><ul><li>Token: <code>POST https://services.apinaranja.com/security-ms/api/security/auth0/b2b/m2ms</code> (<code>client_credentials</code> con <code>client_id</code>, <code>client_secret</code>, <code>audience</code>); API <code>https://api.ranty.io</code> (<code>PMW/NaranjaX/Service.cs:19-21</code>). El token se cachea <strong>sin controlar vencimiento</strong> (<code>PMW/NaranjaX/Functions.cs:40-62</code>).</li><li>Endpoints: <code>POST api/payment_request/dynamic_qr</code> → <code>id</code>, <code>qr_data</code>; <code>GET api/payment_request/{id}/payments</code> (estado <code>APPROVED</code>).</li><li>Parámetros 2756-2758 (credenciales) y 2762 (<code>pos_id</code>).</li><li>Solo QR dinámico en caja: <code>Create_Request</code> (<code>RN.Cob/clsNaranjaX.cs:222-260</code>) usa <code>external_payment_id = COD_PAG + &quot;-&quot; + código de cliente Procoop</code>, <code>callback_url</code> <strong>hardcodeada</strong> a un endpoint de CoopOnline con identificadores fijos en la ruta (<code>:251</code>) y <code>duration_time</code> calculado como hoy menos el vencimiento, que da <strong>negativo</strong> (<code>:255</code>, probable bug). El id externo se guarda en <code>URL_SUCCESS</code>. <code>Registrar_Solicitudes</code> (links) no está implementado (<code>:396-400</code>). Confirmación en <code>Obtener_Pago</code> (<code>:332-390</code>) + polling de caja.</li></ul><hr><h2 id="_8-payfun" tabindex="-1">8. PayFun <a class="header-anchor" href="#_8-payfun" aria-label="Permalink to &quot;8. PayFun&quot;">​</a></h2><ul><li><code>https://checkouts.payfun.com.ar/v2</code>, headers <code>x-api-key</code> y <code>x-access-token</code>, User-Agent &quot;PROCOOP&quot; (<code>PMW/PayFun/Service.cs:18-29</code>). <code>POST checkout</code> → <code>form_url</code>, <code>form_qr_url</code>; <code>GET payments/details/{cod_pag}</code> (<code>PMW/PayFun/Functions.cs:12-22</code>).</li><li>Parámetros: 2793 API key, 2794 token, 2795 URL de retorno, 2796 notificación, 2816 medios, 2820 deuda total, 2822 importe mínimo para Pago Fácil.</li><li><code>Generar_Solicitud</code> (<code>RN.Cob/clsPayFun.cs:298-345</code>): <code>payment_methods</code> entre <code>pagofacil</code>, <code>debin</code>, <code>tarjeta</code>; origen &quot;CoopOnline&quot;; vence al día siguiente. Pagado si el estado es <code>CAPTURED</code> o <code>AUTHORISED</code> (<code>Obtener_Pago</code> <code>:202-251</code>).</li></ul><h2 id="_9-pagos-tic-paypertic" tabindex="-1">9. Pagos TIC (PayPerTIC) <a class="header-anchor" href="#_9-pagos-tic-paypertic" aria-label="Permalink to &quot;9. Pagos TIC (PayPerTIC)&quot;">​</a></h2><ul><li>Sesión <code>https://a.paypertic.com/auth/realms/entidades/protocol/openid-connect/token</code> (OAuth2 <strong>password grant</strong>: usuario, clave, <code>client_id</code>, <code>client_secret</code>; token reutilizado 5 min); API <code>https://api.paypertic.com</code> (<code>PMW/Pagostic/Service.cs:14-16</code>, <code>Functions.cs:23-75</code>).</li><li><code>POST pagos</code> → <code>id</code>, <code>form_url</code>; <code>GET pagos/{id}</code> (estado <code>approved</code>, <code>RN.Cob/clsPagostic.cs:198-237</code>). Parámetros 2877-2883.</li></ul><h2 id="_10-sipago-geopagos" tabindex="-1">10. SiPago (Geopagos) <a class="header-anchor" href="#_10-sipago-geopagos" aria-label="Permalink to &quot;10. SiPago (Geopagos)&quot;">​</a></h2><ul><li>Token <code>https://auth.prd.geopagos.io/oauth/token</code> (<code>client_credentials</code>, scope <code>*</code>); API <code>https://api.sipago.coop</code> (<code>PMW/SiPago/Service.cs:18-27</code>).</li><li><code>POST/GET api/v2/orders</code>: importe <strong>en centavos</strong>, moneda &quot;032&quot;, <code>webhookUrl</code>, redirecciones de éxito/fallo → <code>uuid</code>, <code>links.checkout</code>; estados <code>PENDING</code> / <code>SUCCESS</code> (<code>RN.Cob/clsSiPago.cs:52-116</code>, <code>:231-300</code>). Parámetros 2956-2960.</li><li>Registra <code>FECHA_PAG = FEC_REG</code> (fecha de la solicitud, no la del pago real).</li></ul><h2 id="_11-helipagos" tabindex="-1">11. Helipagos <a class="header-anchor" href="#_11-helipagos" aria-label="Permalink to &quot;11. Helipagos&quot;">​</a></h2><ul><li><code>https://api.helipagos.com</code>, Bearer con API key (3077). <code>POST api/solicitud_pago/v1/checkout/solicitud_pago</code> (importe en centavos con ceros a 10, <code>fecha_vto</code>, <code>fecha_2do_vto</code>, <code>recargo</code>, <code>referencia_externa</code>, <code>url_redirect</code> 3078, <code>webhook</code> 3079, <code>qr = true</code>) → <code>id_sp</code>, <code>codigo_barra</code>, <code>checkout_url</code>, <code>qr_data</code>. Consulta <code>POST get_solicitud_pago?referencia_externa=</code> (estados <code>PROCESADA</code>/<code>ACREDITADA</code>, <code>importe_pagado</code>, <code>fecha_acreditacion</code>) (<code>PMW/Helipagos/Functions.cs:11-19</code>; <code>RN.Cob/clsHelipagos.cs:128-184</code>, <code>:323-393</code>).</li></ul><h2 id="_12-provincianet-banco-provincia-qr" tabindex="-1">12. ProvinciaNet (Banco Provincia, QR) <a class="header-anchor" href="#_12-provincianet-banco-provincia-qr" aria-label="Permalink to &quot;12. ProvinciaNet (Banco Provincia, QR)&quot;">​</a></h2><ul><li><code>https://netqr-bff-tenant.provincianet.com.ar</code>, header <code>x-api-key</code> (3046) (<code>PMW/ProvinciaNet/Service.cs:24-32</code>).</li><li>Endpoints (<code>PMW/ProvinciaNet/Functions.cs:13-36</code>): <code>GET api/v1/public/healthcheck</code>; <code>POST api/v1/qrs/generate_qrs</code> (lote de <code>tx_id</code>, <code>amount_1..3</code>, <code>date_1..3</code>) → <code>batch_uuid</code>; <code>GET qrs/batches/{id}/status_api</code>; <code>GET get_qrs_text?batch_uuid=…</code> (la URL lleva un segundo <code>?</code> en lugar de <code>&amp;</code>, <code>:30</code>, bug).</li><li><code>GenerarLoteQr</code> (<code>RN.Cob/clsProvinciaNet.cs:257-347</code>): envía el lote, <strong>espera 10 s fijos</strong> (<code>:311</code>) y consulta; parámetro 3199 (días). Guarda el JSON del lote en log.</li><li><strong><code>Obtener_Pago</code> no consulta la API</strong>: toma como pagado el importe <code>pagado</code> que llega desde el portal (<code>:95-143</code>). Es el único conector donde la confirmación depende enteramente de un dato externo no verificado.</li></ul><h2 id="_13-prontopago-qr-en-facturas" tabindex="-1">13. ProntoPago (QR en facturas) <a class="header-anchor" href="#_13-prontopago-qr-en-facturas" aria-label="Permalink to &quot;13. ProntoPago (QR en facturas)&quot;">​</a></h2><ul><li><code>https://qrfacturas.prontopago.com.ar</code>: <code>POST api/v1/authorization</code> (clave pública/privada → token de 1 h), <code>POST api/v1/qr</code> (<code>servicio</code>, <code>clientes[]</code>) → <code>qrs</code> (<code>PMW/ProntoPago/Functions.cs:17-50</code>). Parámetros 2969-2971.</li><li><code>InformarQrs</code> (<code>RN.Cob/clsProntoPago.cs:220-265</code>) en lotes de 100; descarta importes ≤ $10. <code>Obtener_Pago</code> no está implementado (<code>:332-335</code>): los pagos entran por el archivo de rendición &quot;ProntoPago_QR&quot; (doc 05).</li></ul><h2 id="_14-offline-y-resumen-de-tarjeta-de-terceros" tabindex="-1">14. OffLine y resumen de tarjeta de terceros <a class="header-anchor" href="#_14-offline-y-resumen-de-tarjeta-de-terceros" aria-label="Permalink to &quot;14. OffLine y resumen de tarjeta de terceros&quot;">​</a></h2><ul><li><strong>OffLine</strong> (API 3): no hay pasarela; el portal genera un cupón (PDF) para pagar en un ente presencial y el pago entra por la rendición por archivo (doc 05; parámetro 2645).</li><li><strong>BancoSangre</strong>: <code>POST https://www.bancodesangre.cooponlineweb.com.ar/api/ResumenTarjeta/GetResumen</code> (sucursal, DNI, CUIT → resumen de tarjeta, importe total y mínimo, vencimiento), <strong>sin autenticación</strong> (<code>PMW/BancoSangre/Service.cs:13</code>, <code>Functions.cs:9-13</code>). Lo usa <code>clsTerceros.GetResumen</code> (<code>RN.Cob/clsTerceros.cs:206</code>) para cobrar en caja/portal resúmenes de tarjeta de una entidad de terceros (parámetro 3114; <code>clsWeb_CoopOnline.CrearCobranzaResumenTarjeta</code>, <code>Agente/clsWeb_CoopOnline.cs:1324-1370</code>). El nombre del servicio no tiene relación con un banco de sangre real: es un servicio del proveedor alojado en el dominio CoopOnline.</li></ul><h2 id="_15-cobertura-por-tipo-de-medio" tabindex="-1">15. Cobertura por tipo de medio <a class="header-anchor" href="#_15-cobertura-por-tipo-de-medio" aria-label="Permalink to &quot;15. Cobertura por tipo de medio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesidad</th><th>Cómo se resuelve hoy</th></tr></thead><tbody><tr><td>Link / botón de pago</td><td>Pagos360, SIRO, MercadoPago, Macro, PayFun, Pagos TIC, SiPago, Helipagos</td></tr><tr><td>QR dinámico en caja</td><td>Pagos360, SIRO (EMVCo local), NaranjaX</td></tr><tr><td>QR estático por caja</td><td>Pagos360 (<code>CAJAS_QR</code>), SIRO</td></tr><tr><td>QR impreso en factura</td><td>Pagos360 (<code>GenerarQr360</code>), ProvinciaNet, ProntoPago</td></tr><tr><td>Pago Fácil / Rapipago &quot;online&quot;</td><td>Códigos de barras de Pagos360 / Helipagos, PayFun; si no, archivo (doc 05)</td></tr><tr><td>Débito automático tarjeta / CBU por API</td><td>Solo Pagos360; el resto por archivo (doc 05 §6)</td></tr><tr><td>DEBIN</td><td>Como canal dentro de Pagos360 o PayFun</td></tr><tr><td>Red Link / Banelco</td><td>Como canal de Pagos360 (<code>link_pagos</code>, <code>banelco_pmc</code>); si no, archivo</td></tr><tr><td>Devoluciones</td><td>No implementadas en ninguna pasarela</td></tr><tr><td>Contracargos</td><td>Solo Pagos360 (reporte + anticipo de reversión)</td></tr></tbody></table><hr><h2 id="_16-interbanking" tabindex="-1">16. Interbanking <a class="header-anchor" href="#_16-interbanking" aria-label="Permalink to &quot;16. Interbanking&quot;">​</a></h2><p>Interbanking aparece de dos formas independientes: una <strong>API de información financiera</strong> (solo lectura, para saldos y conciliación) y <strong>archivos de pago</strong> para subir a la banca electrónica. No hay transferencias por API.</p><h3 id="_16-1-api-pmw-interbanking" tabindex="-1">16.1 API (<code>PMW/Interbanking/</code>) <a class="header-anchor" href="#_16-1-api-pmw-interbanking" aria-label="Permalink to &quot;16.1 API (\`PMW/Interbanking/\`)&quot;">​</a></h3><ul><li>Token: <code>POST https://auth.interbanking.com.ar/cas/oidc/accessToken</code> con <code>grant_type=client_credentials</code> en formulario y <code>scope=info-financiera</code> (<code>PMW/Interbanking/Service.cs:21</code>, <code>Functions.cs:9-11</code>, <code>Login</code> <code>:48-70</code>).</li><li>API: <code>https://api-gw.interbanking.com.ar/api/prod/v1/</code> y <code>/v2/</code> (<code>Service.cs:23-25</code>). Headers: <code>Authorization: Bearer</code>, <code>client_id</code> y un header <code>service</code> con una URL fija del proveedor de Procoop (<code>:79</code>), que parece identificar la aplicación registrada ante Interbanking.</li><li>Endpoints (<code>Functions.cs:21-34</code>): <code>GET accounts?customer-id=</code> (cuentas), <code>GET accounts/balances?customer-id=</code> (saldos), <code>GET v2 accounts/{nro}/movements/anteriores?bank-number&amp;customer-id&amp;date-since&amp;page&amp;account-type</code> (movimientos de días anteriores, paginados). No se usan movimientos del día.</li><li>Credenciales: tabla <strong><code>INTERBANKING</code></strong> (<code>CLIENT_ID</code>, <code>CLIENT_SECRET</code>, <code>ACCESS_TOKEN</code>, <code>EXP_TOKEN</code>, <code>CUSTOMER_ID</code>). El token se persiste en la tabla con vencimiento de 7200 s y se reutiliza.</li></ul><h3 id="_16-2-saldos-y-movimientos-rn-tes-clsinterbanking-cs" tabindex="-1">16.2 Saldos y movimientos (<code>RN.Tes/clsInterbanking.cs</code>) <a class="header-anchor" href="#_16-2-saldos-y-movimientos-rn-tes-clsinterbanking-cs" aria-label="Permalink to &quot;16.2 Saldos y movimientos (\`RN.Tes/clsInterbanking.cs\`)&quot;">​</a></h3><ul><li>Vinculación de cuentas: <code>BANKOS.CTA_INTERBANKING</code> guarda en JSON la cuenta de Interbanking asociada a cada banco propio (<code>Configuracion/abm_bankos.cs:229-261</code>); <code>getCuentasInterbanking</code> (<code>:133-170</code>) lista las cuentas disponibles.</li><li><code>getSaldosCuentasInterbanking</code> (<code>:172-243</code>): compara el saldo bancario informado con el saldo contable de <code>RESBAN</code> por <code>COD_BAN</code>. Pantalla <code>frmSaldosCuentasInterbanking</code>.</li><li><code>getMovimientosCuentaInterbanking</code> (<code>:245-353</code>): pagina, <strong>deduplica</strong> por cuenta + importe + correlativo + fechas y guarda en <code>MOV_INTERBANKING</code>; el código de operación de Interbanking se traduce a un concepto de Procoop por <code>CON_COM.COD_IB</code> (<code>getCodConCom</code> <code>:626-632</code>).</li></ul><h3 id="_16-3-conciliacion-bancaria" tabindex="-1">16.3 Conciliación bancaria <a class="header-anchor" href="#_16-3-conciliacion-bancaria" aria-label="Permalink to &quot;16.3 Conciliación bancaria&quot;">​</a></h3><ul><li>Pantalla <code>frmConciliacionInterbanking</code> (menú en <code>clsDefault.cs:459-460</code>, <code>clsChequeosMenu.cs:858-859</code>). Muestra a la izquierda los movimientos bancarios (<code>GetMovimientosInterbank</code> <code>:355-412</code>) y a la derecha los de libro (<code>GetMovimientosResban</code> <code>:414-452</code>), con filtro de estado 1 conciliado, 2 no conciliado, 3 por fecha de conciliación.</li><li><code>GuardarConciliacion</code> (<code>:479-508</code>): el usuario selecciona N movimientos de banco y M de libro y se graba un grupo <code>COD_CONC</code> en <code>RESBAN_MOVINT</code> (conciliación <strong>manual, muchos a muchos</strong>). <code>EliminarConciliacion</code> (<code>:510-520</code>) deshace el grupo. La fecha de conciliación queda en <code>RESBAN.FEC_CONC_INT</code> (<code>RN.Tes/clsTesoreria.cs:1165-1205</code>).</li><li>No hay conciliación automática por reglas (importe/fecha/referencia).</li></ul><h3 id="_16-4-archivos-de-pago-proveedores-y-sueldos" tabindex="-1">16.4 Archivos de pago (proveedores y sueldos) <a class="header-anchor" href="#_16-4-archivos-de-pago-proveedores-y-sueldos" aria-label="Permalink to &quot;16.4 Archivos de pago (proveedores y sueldos)&quot;">​</a></h3><ul><li><strong>Pago a proveedores</strong> — <code>GenerarArchivosInterbanking</code> (<code>ReglasNegocio/ReglasNegocio.Facturacion/clsInformes_Compras.cs:3447-3495</code>): cabecera <code>*U*</code> + CBU de origen (22) + &quot;D&quot; + fecha…; detalle <code>*M*</code> + CBU del proveedor + importe en centavos (17) + concepto (60) + tipo, sucursal y número de comprobante + retención. CBU de origen de la entidad o parámetro 2573. Hay variante Credicoop en planilla (<code>:3497</code>).</li><li><strong>Transferencias desde tesorería</strong> — <code>clsProveedor.ExportarArchivo_Interbanking</code> (<code>ReglasNegocio/clsProveedor.cs:163-204</code>): usa el parámetro <strong>2262 (CBU de sueldos)</strong> como origen y marca <code>RESBAN.GEN_ARCHIVO</code>. Que use el CBU de sueldos y no el 2573 parece una inconsistencia (duda abierta).</li><li><strong>Sueldos</strong> — <code>clsInformes_Sueldo.ExportarArchivoInterbanking</code> (<code>ReglasNegocio/RN.Sueldos/clsInformes_Sueldo.cs:2245-2315</code>): CBU de origen 2262, CBU del empleado; con 3129 reparte entre varias cuentas del empleado. Pantalla <code>frmExportadorInterBanking</code> (<code>clsChequeosMenu.cs:411</code>).</li></ul><hr><h2 id="_17-hallazgos-de-seguridad" tabindex="-1">17. Hallazgos de seguridad <a class="header-anchor" href="#_17-hallazgos-de-seguridad" aria-label="Permalink to &quot;17. Hallazgos de seguridad&quot;">​</a></h2><p>Sin transcribir valores; solo tipo y ubicación.</p><table tabindex="0"><thead><tr><th>Hallazgo</th><th>Tipo de secreto / dato</th><th>Ubicación</th></tr></thead><tbody><tr><td>El log de Pagos360 escribe el header de autorización completo y el cuerpo si existe <code>c:\\procoop\\Log360.txt</code></td><td>API key Bearer en texto plano en disco</td><td><code>PMW/Pagos360/Service.cs:39-76</code></td></tr><tr><td>El string del botón Macro incluye la clave secreta en claro; se guarda en <code>PAGOS360.URL_SUCCESS</code> y viaja al portal</td><td>Clave secreta de comercio (firma)</td><td><code>RN.Cob/clsMacro.cs:209-258</code>; <code>Agente/clsWeb_CoopOnline.cs:1365-1368</code></td></tr><tr><td>Credenciales de pasarelas en parámetros <code>V2_*</code> sin cifrar</td><td>Tokens, claves, client_secret</td><td>parámetros listados en cada sección (doc 09)</td></tr><tr><td>Credenciales y token de Interbanking en tabla sin cifrar</td><td>client_secret, access_token</td><td>tabla <code>INTERBANKING</code>; <code>RN.Tes/clsInterbanking.cs</code></td></tr><tr><td>Datos de tarjeta (número, vencimiento, código de seguridad) inyectados en un HTML local en el tótem</td><td>Datos PCI</td><td><code>RN.Cob/clsPagos360.cs:367-382</code></td></tr><tr><td>ProvinciaNet acepta como pagado el importe que informa el portal, sin consultar al banco</td><td>Integridad del cobro</td><td><code>RN.Cob/clsProvinciaNet.cs:95-143</code></td></tr><tr><td>SQL armado por concatenación al guardar datos de solicitudes</td><td>Inyección SQL (datos de la pasarela)</td><td><code>RN.Cob/clsPagos360.cs:2417</code>; <code>RN.Cob/clsMacro.cs:238-258</code></td></tr><tr><td>Servicio BancoSangre sin autenticación devuelve resúmenes de tarjeta por DNI/CUIT</td><td>Datos personales</td><td><code>PMW/BancoSangre/Service.cs:13</code></td></tr></tbody></table><p>No se encontraron credenciales hardcodeadas en <code>ProMod_WebService</code>, <code>MercadoPago</code> ni <code>PlusPagosSecurityKitNetFramework</code>.</p><hr><h2 id="_18-resto-de-promod-webservice" tabindex="-1">18. Resto de <code>ProMod_WebService</code> <a class="header-anchor" href="#_18-resto-de-promod-webservice" aria-label="Permalink to &quot;18. Resto de \`ProMod_WebService\`&quot;">​</a></h2><p>Además de las pasarelas e Interbanking, el ensamblado solo contiene <code>WebService.BancoSangre</code> (§14) y <code>WebService.Util/CoreUtils</code> (deserialización y log). <strong>No contiene</strong> los clientes de CoopOnline, la app, SMS, WhatsApp, mail ni Firebase: esos están en <code>ReglasNegocio</code> (<code>Agente.Clases</code>, <code>RN.Titulares/clsWEB</code>, etc.) y se describen en <a href="./10-integraciones-externas">doc 10</a>.</p><hr><h2 id="_19-implicancias-para-goodapps" tabindex="-1">19. Implicancias para GoodApps <a class="header-anchor" href="#_19-implicancias-para-goodapps" aria-label="Permalink to &quot;19. Implicancias para GoodApps&quot;">​</a></h2><h3 id="_19-1-prioridades" tabindex="-1">19.1 Prioridades <a class="header-anchor" href="#_19-1-prioridades" aria-label="Permalink to &quot;19.1 Prioridades&quot;">​</a></h3><ol><li><strong>Para el piloto LAG</strong> alcanza con <strong>SIRO</strong>: el botón de pago para CoopOnline, sobre todo para recargas de energía prepaga, y el envío y la rendición por archivo. La base de LAG no tiene ninguna otra pasarela configurada (<a href="./12-configuracion-real-laguna-larga">doc 12 §3</a>).</li><li><strong>Pagos360</strong> primero entre las de link: cubre link, QR, Rapipago/Pago Fácil por código de barras, débito tarjeta/CBU y contracargos con una sola integración.</li><li><strong>Interbanking</strong>: saldos + movimientos + conciliación es valor alto y API simple (3 endpoints de lectura). Los archivos de pago a proveedores/sueldos son exportadores de formato fijo.</li><li>El resto (NaranjaX, PayFun, Pagos TIC, SiPago, Helipagos, ProvinciaNet, ProntoPago, Macro) solo si alguna cooperativa los usa: migrar bajo demanda.</li></ol><h3 id="_19-2-diseno-generico-propuesto" tabindex="-1">19.2 Diseño genérico propuesto <a class="header-anchor" href="#_19-2-diseno-generico-propuesto" aria-label="Permalink to &quot;19.2 Diseño genérico propuesto&quot;">​</a></h3><ul><li><strong>Un modelo único de &quot;intención de pago&quot;</strong> (equivalente a <code>PAGOS360</code> + ítems + pagos) con estados explícitos y una máquina de estados validada: <code>pendiente → emitida → pagada → imputada</code>, más <code>anulada</code>, <code>vencida</code>, <code>rechazada</code>, <code>revertida</code>, <code>devuelta</code>.</li><li><strong>Interfaz de conector</strong> con operaciones <code>crear</code>, <code>consultar</code>, <code>listarCobranzas(rango)</code>, <code>cancelar</code>, <code>devolver</code> y, opcionalmente, <code>adherirDebito</code> / <code>emitirDebito</code> / <code>contracargos</code>; capacidades declaradas por conector (no <code>NotImplementedException</code>).</li><li><strong>Credenciales por cooperativa</strong> en un almacén de secretos (no en parámetros ni tablas), con ambiente sandbox/producción configurable por conector y URLs base configurables.</li><li><strong>Idempotencia</strong>: clave externa = id de la intención; deduplicación de pagos por id de pago externo (como hace Procoop), y reutilización de links vigentes.</li><li><strong>Importes recalculados con las reglas de doc 05</strong> al emitir; al confirmar, aceptar el importe pagado aunque hoy el cálculo dé distinto (evitar el bloqueo de &quot;importes no coinciden&quot; y mandarlo a una cola de revisión).</li></ul><h3 id="_19-3-webhooks-vs-polling" tabindex="-1">19.3 Webhooks vs. polling <a class="header-anchor" href="#_19-3-webhooks-vs-polling" aria-label="Permalink to &quot;19.3 Webhooks vs. polling&quot;">​</a></h3><ul><li><strong>Webhooks recibidos por GoodApps</strong> (endpoint propio por conector, sin pasar por Firebase), tratados como disparadores: siempre re-consultar la API antes de marcar pagado, igual que hace Procoop, y validar firma cuando el proveedor la ofrezca.</li><li><strong>Polling de conciliación diario</strong> (reporte de cobranza / listado) como red de seguridad, con ventana configurable (Procoop usa 4 días) y alta de pagos sin intención previa (&quot;pago app&quot;).</li><li><strong>Polling corto solo para caja con QR</strong>, preferentemente reemplazado por webhook + notificación en tiempo real a la caja.</li><li>Reintentos con backoff y timeouts explícitos, cola de mensajes para los webhooks y registro de auditoría sin secretos (corregir el caso del log de Pagos360).</li><li>Evitar esperas fijas (25 s de SIRO, 10 s de ProvinciaNet): usar consulta asíncrona.</li></ul><h3 id="_19-4-no-replicar" tabindex="-1">19.4 No replicar <a class="header-anchor" href="#_19-4-no-replicar" aria-label="Permalink to &quot;19.4 No replicar&quot;">​</a></h3><p>Credenciales estáticas por proceso, secretos en logs/campos de la base o enviados al portal, SQL concatenado, confirmación sin consultar a la pasarela (ProvinciaNet), emparejamiento por fecha+importe del QR estático (asignar una referencia por transacción), manejo de datos de tarjeta en el tótem (usar formularios alojados por la pasarela).</p><hr><h2 id="_20-dudas-abiertas" tabindex="-1">20. Dudas abiertas <a class="header-anchor" href="#_20-dudas-abiertas" aria-label="Permalink to &quot;20. Dudas abiertas&quot;">​</a></h2><ol><li><s>¿Qué pasarelas usa hoy LAG y con qué volumen? ¿Usa Interbanking?</s> <strong>Respondida</strong> en la base demo (<a href="./12-configuracion-real-laguna-larga">doc 12 §3</a>). Usa solo el botón SIRO: 128.776 solicitudes entre 2023 y 2026, cerca del 70 % de energía prepaga. Las demás pasarelas no tienen credenciales y la tabla <code>INTERBANKING</code> está vacía.</li><li>El backend CoopOnline que recibe los webhooks (<code>TipCobrador</code>/<code>CodPag</code>) no está en el descompilado: ¿valida algo antes de escribir en Firebase? ¿GoodApps reemplaza también ese componente?</li><li>¿Las claves de Pagos360 con prefijo &quot;TEST&quot; eran claves de sandbox usadas contra producción? ¿Existió alguna vez un ambiente de homologación configurable?</li><li>Cancelación de débito CBU en Pagos360 con <code>GET</code> en lugar de <code>PUT</code>: ¿funciona o es un bug latente?</li><li>Macro: ¿quién calcula el hash del formulario (el portal)? ¿Por qué se guarda y envía la clave secreta junto con los datos cifrados?</li><li>ProvinciaNet: ¿de dónde sale el importe <code>pagado</code> que llega al Agente y quién lo garantiza?</li><li>NaranjaX: el <code>duration_time</code> negativo y el <code>callback_url</code> fijo, ¿funcionaban en producción?</li><li>Interbanking: ¿la aplicación registrada (header <code>service</code> y <code>client_id</code>) es del proveedor de Procoop o de cada cooperativa? ¿Hay que tramitar credenciales propias para GoodApps?</li><li><code>clsProveedor.ExportarArchivo_Interbanking</code> usa el CBU de sueldos (2262) como origen de pagos a proveedores: ¿intencional?</li><li>Devoluciones: ¿cómo se resuelven hoy (manual en el panel de la pasarela + nota de crédito)? ¿GoodApps debe integrarlas por API?</li><li>¿Se usan efectivamente PayFun, Pagos TIC, SiPago, Helipagos y ProntoPago en alguna cooperativa del parque, o son integraciones hechas para un único cliente?</li></ol>`,123)])])}const m=o(t,[["render",r]]);export{g as __pageData,m as default};
